-- Prices per weight live inside "variants". On a re-run, refresh them without touching stock:
update products set variants = (select jsonb_agg(case when e->>'label' = '250 جم' then e || '{"price":225,"opts":{"weight":"250 جم"},"labelEn":"250 g"}'::jsonb when e->>'label' = '1 كجم' then e || '{"price":900,"opts":{"weight":"1 كجم"},"labelEn":"1 kg"}'::jsonb else e end) from jsonb_array_elements(variants) e) where id = 'bonds-chrome';
update products set variants = (select jsonb_agg(case when e->>'label' = '250 جم' then e || '{"price":245,"opts":{"weight":"250 جم"},"labelEn":"250 g"}'::jsonb when e->>'label' = '1 كجم' then e || '{"price":980,"opts":{"weight":"1 كجم"},"labelEn":"1 kg"}'::jsonb else e end) from jsonb_array_elements(variants) e) where id = 'bonds-amber';
update products set variants = (select jsonb_agg(case when e->>'label' = '250 جم' then e || '{"price":500,"opts":{"weight":"250 جم"},"labelEn":"250 g"}'::jsonb when e->>'label' = '1 كجم' then e || '{"price":2000,"opts":{"weight":"1 كجم"},"labelEn":"1 kg"}'::jsonb else e end) from jsonb_array_elements(variants) e) where id = 'bonds-ethiopia-guji';
update products set variants = (select jsonb_agg(case when e->>'label' = '250 جم' then e || '{"price":300,"opts":{"weight":"250 جم"},"labelEn":"250 g"}'::jsonb when e->>'label' = '1 كجم' then e || '{"price":1200,"opts":{"weight":"1 كجم"},"labelEn":"1 kg"}'::jsonb else e end) from jsonb_array_elements(variants) e) where id = 'bonds-ethiopia-limu';
update products set variants = (select jsonb_agg(case when e->>'label' = '250 جم' then e || '{"price":325,"opts":{"weight":"250 جم"},"labelEn":"250 g"}'::jsonb when e->>'label' = '1 كجم' then e || '{"price":1300,"opts":{"weight":"1 كجم"},"labelEn":"1 kg"}'::jsonb else e end) from jsonb_array_elements(variants) e) where id = 'bonds-brazil-red-catuai';
update products set variants = (select jsonb_agg(case when e->>'label' = '250 جم' then e || '{"price":375,"opts":{"weight":"250 جم"},"labelEn":"250 g"}'::jsonb when e->>'label' = '1 كجم' then e || '{"price":1500,"opts":{"weight":"1 كجم"},"labelEn":"1 kg"}'::jsonb else e end) from jsonb_array_elements(variants) e) where id = 'bonds-colombia-castillo';
update products set variants = (select jsonb_agg(case when e->>'label' = '250 جم' then e || '{"price":450,"opts":{"weight":"250 جم"},"labelEn":"250 g"}'::jsonb when e->>'label' = '1 كجم' then e || '{"price":1800,"opts":{"weight":"1 كجم"},"labelEn":"1 kg"}'::jsonb else e end) from jsonb_array_elements(variants) e) where id = 'bonds-el-salvador';

-- Coffees no longer sold: hidden (kept for past orders).
update products set status = 'hidden' where id in ('bonds-sienna', 'bonds-brazil-cerrado');

commit;

